steps.action_code:
dated_dinner_notes = [n for n in dinner_notes if str(n["created_at"]).startswith(yesterday_date) or str(n["updated_at"]).startswith(yesterday_date)]
if not dated_dinner_notes:
    raise ValueError("No dinner note from yesterday was found")

def note_relevance(note):
    title_text = str(note["title"]).lower()
    content_text = str(note["content"]).lower()
    return (3 if "dinner" in title_text else 0) + (2 if "friend" in title_text else 0) + (1 if "dinner" in content_text else 0)

dated_dinner_notes.sort(key=lambda n: (note_relevance(n), str(n["updated_at"]), n["note_id"]), reverse=True)
selected_note = dated_dinner_notes[0]

def word_tokens(value):
    cleaned = "".join(ch.lower() if ch.isalnum() else " " for ch in str(value))
    return [part for part in cleaned.split() if part]

parsed_share_candidates = []
for raw_line in str(selected_note["content"]).replace(";", "\n").splitlines():
    line = raw_line.strip().lstrip("-*•").strip()
    if not line:
        continue
    amount = None
    name_part = ""
    dollar_position = line.rfind("$")
    if dollar_position >= 0:
        cursor = dollar_position + 1
        while cursor < len(line) and line[cursor].isspace():
            cursor += 1
        end = cursor
        while end < len(line) and (line[end].isdigit() or line[end] in ".,"):
            end += 1
        numeric_text = line[cursor:end].replace(",", "")
        if numeric_text:
            try:
                amount = float(numeric_text)
                name_part = line[:dollar_position]
            except ValueError:
                amount = None
    if amount is None:
        for token in reversed(line.split()):
            numeric_text = token.strip("$,;:()[]{}").replace(",", "")
            try:
                possible_amount = float(numeric_text)
            except ValueError:
                continue
            amount = possible_amount
            name_part = line[:line.rfind(token)]
            break
    name_part = name_part.strip(" \t:-–—")
    label_tokens = word_tokens(name_part)
    if amount is None or amount <= 0 or not label_tokens:
        continue
    if set(label_tokens) & {"total", "subtotal", "date", "bill", "tax", "tip"}:
        continue
    parsed_share_candidates.append({"name": name_part, "amount": round(amount, 2)})

share_rows = []
unresolved_shares = []
for share in parsed_share_candidates:
    share_tokens = word_tokens(share["name"])
    share_key = "".join(share_tokens)
    scored_contacts = []
    for contact in friend_contacts:
        first_tokens = word_tokens(contact["first_name"])
        last_tokens = word_tokens(contact["last_name"])
        first_key = "".join(first_tokens)
        last_key = "".join(last_tokens)
        full_key = first_key + last_key
        score = 0
        if share_key == full_key:
            score = 5
        elif share_key == first_key or share_key == last_key:
            score = 4
        elif first_key in share_tokens and last_key in share_tokens:
            score = 3
        elif first_key and first_key in share_tokens:
            score = 2
        if score:
            scored_contacts.append((score, contact))
    if scored_contacts:
        top_score = max(item[0] for item in scored_contacts)
        best_contacts = [item[1] for item in scored_contacts if item[0] == top_score]
    else:
        best_contacts = []
    if len(best_contacts) == 1:
        matched_contact = best_contacts[0]
        share_rows.append({"name": share["name"], "amount": share["amount"], "contact": matched_contact})
    else:
        unresolved_shares.append(share)
print({"selected_note": {"note_id": selected_note["note_id"], "title": selected_note["title"]}, "matched_shares": [{"name": row["name"], "email": row["contact"]["email"], "amount": row["amount"]} for row in share_rows], "unresolved_shares": unresolved_shares})

paid_share_rows = []
request_targets = []
for row in share_rows:
    contact_email = str(row["contact"]["email"]).lower()
    matching_receipts = [tx for tx in received_transactions if str(tx["sender"]["email"]).lower() == contact_email and abs(float(tx["amount"]) - float(row["amount"])) < 0.005]
    if matching_receipts:
        paid_share_rows.append(row)
    else:
        request_targets.append({"name": row["name"], "user_email": row["contact"]["email"], "amount": row["amount"]})

resolved_emails = [str(row["contact"]["email"]).lower() for row in share_rows]
duplicate_share_emails = sorted({email for email in resolved_emails if resolved_emails.count(email) > 1})
review_issues = []
if not parsed_share_candidates:
    review_issues.append("No positive share rows were parsed")
if unresolved_shares:
    review_issues.append("At least one parsed share did not resolve uniquely")
if duplicate_share_emails:
    review_issues.append("A contact appeared more than once in the share rows")
if any(not target["user_email"] or target["amount"] <= 0 for target in request_targets):
    review_issues.append("A request target lacks a valid email or positive amount")
print({"already_paid": [{"name": row["name"], "email": row["contact"]["email"], "amount": row["amount"]} for row in paid_share_rows], "requests_to_create": request_targets, "review_issues": review_issues})
if review_issues:
    raise ValueError("; ".join(review_issues))

verification_contacts = []
verification_contact_page_index = 0
while True:
    verification_contact_page = apis.phone.search_contacts(access_token=phone_access_token, query="", relationship="friend", page_index=verification_contact_page_index, page_limit=20)
    verification_contacts.extend(verification_contact_page)
    if len(verification_contact_page) < 20:
        break
    verification_contact_page_index += 1

verification_note = apis.simple_note.show_note(note_id=selected_note["note_id"], access_token=simple_note_access_token)

verification_transactions = []
verification_transaction_page_index = 0
while True:
    verification_transaction_page = apis.venmo.show_transactions(access_token=venmo_access_token, direction="received", min_created_at=yesterday_date, page_index=verification_transaction_page_index, page_limit=20, sort_by="+created_at")
    verification_transactions.extend(verification_transaction_page)
    if len(verification_transaction_page) < 20:
        break
    verification_transaction_page_index += 1

creation_ids = [item["response"].get("payment_request_id") for item in created_payment_requests]
creation_receipts_ok = len(created_payment_requests) == len(request_targets) and all(request_id is not None for request_id in creation_ids) and len(set(creation_ids)) == len(creation_ids)
expected_target_keys = {(str(target["user_email"]).lower(), round(float(target["amount"]), 2)) for target in request_targets}
created_target_keys = {(str(item["user_email"]).lower(), round(float(item["amount"]), 2)) for item in created_payment_requests}
creation_arguments_ok = expected_target_keys == created_target_keys and all(item["description"] == "Friends Dinner" for item in created_payment_requests)
verification_contact_emails = {str(contact["email"]).lower() for contact in verification_contacts}
contacts_ok = all(str(target["user_email"]).lower() in verification_contact_emails for target in request_targets)
note_ok = verification_note["note_id"] == selected_note["note_id"] and verification_note["content"] == selected_note["content"]

def has_matching_received_payment(row, transactions):
    email = str(row["contact"]["email"]).lower()
    return any(str(tx["sender"]["email"]).lower() == email and abs(float(tx["amount"]) - float(row["amount"])) < 0.005 for tx in transactions)

classification_ok = all(has_matching_received_payment(row, verification_transactions) for row in paid_share_rows) and all(not has_matching_received_payment(row, verification_transactions) for row in share_rows if str(row["contact"]["email"]).lower() in {str(target["user_email"]).lower() for target in request_targets})
verification_passed = creation_receipts_ok and creation_arguments_ok and contacts_ok and note_ok and classification_ok
print({"requested_count": len(request_targets), "creation_receipt_count": len(created_payment_requests), "creation_receipts_ok": creation_receipts_ok, "creation_arguments_ok": creation_arguments_ok, "contacts_ok": contacts_ok, "note_ok": note_ok, "classification_ok": classification_ok, "verification_passed": verification_passed})
if not verification_passed:
    raise ValueError("Post-mutation verification failed")
